  if (err instanceof AppError) {
    const requestId = err.requestId
      ?? readStringField(err.details ?? {}, 'requestId');
    return new AppError(
      err.code,
      err.message,
      err.cause ?? err,
      { ...(err.details ?? {}), ...(details ?? {}) },
      requestId,
