export type AppErrorCode =
  | 'AUTH_INVALID'
  | 'AUTH_PERMANENT'
  | 'TIMEOUT'
  | 'RATE_LIMIT'
  | 'PERMISSION'
  | 'CHANNEL_UNAVAILABLE'
  | 'CONVERSATION_STATE'
  | 'NETWORK'
  | 'CONFIG'
  | 'GATEWAY'
  | 'BILLING'
  | 'OVERLOADED'
  | 'MODEL_NOT_FOUND'
  | 'UNKNOWN';

/**
 * Every class the unified exit can render. Kept as a runtime list so copy,
 * retry and locale coverage can be audited exhaustively instead of by memory.
 */
export const APP_ERROR_CODES = [
  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/** Who is allowed to perform the recovery without elevating host privileges. */
export type RecoveryScope = 'self' | 'user' | 'support' | 'none';

/**
 * Bounded, declarative recovery actions. These values describe a UI or host
 * capability; they are never commands, scripts, shell fragments or executable
 * arguments.
 */
export type NextAction =
  | { kind: 'retry' }
  | { kind: 'reauthenticate' }
  | { kind: 'reconfigure'; target: 'provider' | 'model' | 'conversation' }
  | { kind: 'open-settings'; target: 'authentication' | 'provider' }
  | { kind: 'contact-support' };

export type ErrorRecovery = {
  /** Whether the host may safely repeat the same operation itself. */
  retryable: boolean;
  /** Permission boundary for the suggested recovery. */
  scope: RecoveryScope;
  /** Undefined means that no automatic or actionable recovery is known. */
  nextAction?: NextAction;
  /** Unknown failures must be shown to the user rather than disguised as fixed. */
  exposeRawError: boolean;
};

/**
 * Exhaustive recovery contract for the unified error envelope. The record is
 * intentionally keyed by AppErrorCode so adding a new class fails type checking
 * until its retry, permission scope and user action are reviewed.
 */
export const APP_ERROR_RECOVERY = {
  AUTH_INVALID: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reauthenticate' },
    exposeRawError: false,
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'contact-support' },
    exposeRawError: false,
  },
  TIMEOUT: {
    retryable: true,
    scope: 'self',
    nextAction: { kind: 'retry' },
    exposeRawError: false,
  },
  RATE_LIMIT: {
    retryable: true,
    scope: 'self',
    nextAction: { kind: 'retry' },
    exposeRawError: false,
  },
  PERMISSION: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'contact-support' },
    exposeRawError: false,
  },
  CHANNEL_UNAVAILABLE: {
    retryable: true,
    scope: 'self',
    nextAction: { kind: 'retry' },
    exposeRawError: false,
  },
  CONVERSATION_STATE: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reconfigure', target: 'conversation' },
    exposeRawError: false,
  },
  NETWORK: {
    retryable: true,
    scope: 'self',
    nextAction: { kind: 'retry' },
    exposeRawError: false,
  },
  CONFIG: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reconfigure', target: 'provider' },
    exposeRawError: false,
  },
  GATEWAY: {
    retryable: true,
    scope: 'self',
    nextAction: { kind: 'retry' },
    exposeRawError: false,
  },
  BILLING: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'contact-support' },
    exposeRawError: false,
  },
  OVERLOADED: {
    retryable: true,
    scope: 'self',
    nextAction: { kind: 'retry' },
    exposeRawError: false,
  },
  MODEL_NOT_FOUND: {
    retryable: false,
    scope: 'user',
    nextAction: { kind: 'reconfigure', target: 'model' },
    exposeRawError: false,
  },
  UNKNOWN: {
    retryable: false,
    scope: 'none',
    exposeRawError: true,
  },
} as const satisfies Record<AppErrorCode, ErrorRecovery>;

export function getErrorRecovery(code: AppErrorCode): ErrorRecovery {
  return APP_ERROR_RECOVERY[code];
